    15→
    16→void UCosmeticMainWindow::NativeConstruct()
    17→{
    18→	Super::NativeConstruct();
    19→
    20→	// 모드 탭 버튼 바인딩
    21→	if (ShopTabButton)
    22→	{
    23→		ShopTabButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnShopTabClicked);
    24→		ShopTabButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnShopTabClicked);
    25→	}
    26→
    27→	if (InventoryTabButton)
    28→	{
    29→		InventoryTabButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnInventoryTabClicked);
    30→		InventoryTabButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnInventoryTabClicked);
    31→	}
    32→
    33→	// 슬롯 탭 버튼 바인딩
    34→	if (TabHeadButton)
    35→	{
    36→		TabHeadButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabHeadClicked);
    37→		TabHeadButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabHeadClicked);
    38→	}
    39→
    40→	if (TabBodyButton)
    41→	{
    42→		TabBodyButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabBodyClicked);
    43→		TabBodyButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabBodyClicked);
    44→	}
    45→
    46→	if (TabBackButton)
    47→	{
    48→		TabBackButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabBackClicked);
    49→		TabBackButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabBackClicked);
    50→	}
    51→
    52→	if (TabEffectButton)
    53→	{
    54→		TabEffectButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabEffectClicked);
    55→		TabEffectButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabEffectClicked);
    56→	}
    57→
    58→	// 액션/닫기 버튼 바인딩
    59→	if (ActionButton)
    60→	{
    61→		ActionButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnActionButtonClicked);
    62→		ActionButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnActionButtonClicked);
    63→	}
    64→
    65→	if (CloseButton)
    66→	{
    67→		CloseButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnCloseClicked);
    68→		CloseButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnCloseClicked);
    69→	}
    70→
    71→	// 서브시스템 델리게이트 바인딩
    72→	UGameInstance* GI = GetGameInstance();
    73→	if (GI)
    74→	{
    75→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
    76→		{
    77→			CosmeticSub->OnInventoryUpdated.RemoveDynamic(this, &UCosmeticMainWindow::OnInventoryUpdated);
    78→			CosmeticSub->OnInventoryUpdated.AddDynamic(this, &UCosmeticMainWindow::OnInventoryUpdated);
    79→			CosmeticSub->OnLoadoutChanged.RemoveDynamic(this, &UCosmeticMainWindow::OnLoadoutChanged);
    80→			CosmeticSub->OnLoadoutChanged.AddDynamic(this, &UCosmeticMainWindow::OnLoadoutChanged);
    81→		}
    82→
    83→		if (UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>())
    84→		{
    85→			PurchaseSub->OnPurchaseComplete.RemoveDynamic(this, &UCosmeticMainWindow::OnPurchaseComplete);
    86→			PurchaseSub->OnPurchaseComplete.AddDynamic(this, &UCosmeticMainWindow::OnPurchaseComplete);
    87→		}
    88→
    89→		if (UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>())
    90→		{
