   201→void UCosmeticMainWindow::OnActionButtonClicked()
   202→{
   203→	if (SelectedItemId.IsNone())
   204→	{
   205→		return;
   206→	}
   207→
   208→	UGameInstance* GI = GetGameInstance();
   209→	if (!GI)
   210→	{
   211→		return;
   212→	}
   213→
   214→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   215→	if (!CosmeticSub)
   216→	{
   217→		return;
   218→	}
   219→
   220→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   221→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   222→
   223→	if (CurrentMode == ECosmeticWindowMode::Shop)
   224→	{
   225→		// 상점 모드
   226→		if (CosmeticSub->HasItem(SelectedItemId))
   227→		{
   228→			// 보유 중인 아이템 → 장착 또는 해제
   229→			if (EquippedItem == SelectedItemId)
   230→			{
   231→				CosmeticSub->UnequipSlot(CurrentSlot);
   232→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d (from Shop)"), static_cast<int32>(CurrentSlot));
   233→			}
   234→			else
   235→			{
   236→				CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   237→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d (from Shop)"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   238→			}
   239→			CosmeticSub->SaveLoadoutToLocal();
   240→		}
   241→		else
   242→		{
   243→			// 미보유 아이템 → 재화 구매 우선, 불가 시 Steam 실결제
   244→			const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog() ? CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId) : nullptr;
   245→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   246→
   247→			bool bCurrencyPurchased = false;
   248→			if (ItemDef && CurrencySub)
   249→			{
   250→				if (ItemDef->CoinPrice > 0)
   251→				{
   252→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Coin);
   253→					if (bCurrencyPurchased)
   254→					{
   255→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Coin purchase requested for %s"), *SelectedItemId.ToString());
   256→					}
   257→				}
   258→
   259→				if (!bCurrencyPurchased && ItemDef->GemPrice > 0)
   260→				{
   261→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Gem);
   262→					if (bCurrencyPurchased)
   263→					{
   264→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Gem purchase requested for %s"), *SelectedItemId.ToString());
   265→					}
   266→				}
   267→			}
   268→
   269→			if (!bCurrencyPurchased)
   270→			{
   271→				UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   272→				if (PurchaseSub && !PurchaseSub->IsPurchasePending())
   273→				{
   274→					PurchaseSub->RequestPurchase(SelectedItemId);
   275→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Steam purchase requested for %s"), *SelectedItemId.ToString());
   276→				}
   277→			}
   278→		}
   279→	}
   280→	else
   281→	{
   282→		// 인벤토리 모드: 장착 또는 해제
   283→		if (EquippedItem == SelectedItemId)
   284→		{
   285→			CosmeticSub->UnequipSlot(CurrentSlot);
   286→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d"), static_cast<int32>(CurrentSlot));
   287→		}
   288→		else
   289→		{
   290→			CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   291→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   292→		}
   293→		CosmeticSub->SaveLoadoutToLocal();
   294→	}
   295→}
