   437→void UCosmeticMainWindow::RefreshActionButton()
   438→{
   439→	if (!ActionButton || !ActionButtonText)
   440→	{
   441→		return;
   442→	}
   443→
   444→	if (SelectedItemId.IsNone())
   445→	{
   446→		ActionButton->SetIsEnabled(false);
   447→		ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "SelectItem", "아이템 선택"));
   448→		return;
   449→	}
   450→
   451→	UGameInstance* GI = GetGameInstance();
   452→	if (!GI)
   453→	{
   454→		return;
   455→	}
   456→
   457→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   458→	if (!CosmeticSub)
   459→	{
   460→		return;
   461→	}
   462→
   463→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   464→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   465→	bool bIsEquipped = (EquippedItem == SelectedItemId);
   466→
   467→	if (CurrentMode == ECosmeticWindowMode::Shop)
   468→	{
   469→		// 상점 모드
   470→		if (CosmeticSub->HasItem(SelectedItemId))
   471→		{
   472→			// 보유 중인 아이템 → 장착/해제 가능
   473→			ActionButton->SetIsEnabled(true);
   474→
   475→			if (bIsEquipped)
   476→			{
   477→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   478→			}
   479→			else
   480→			{
   481→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   482→			}
   483→		}
   484→		else
   485→		{
   486→			// 미보유 아이템 → 구매
   487→			UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   488→			bool bPending = PurchaseSub && PurchaseSub->IsPurchasePending();
   489→
   490→			// 재화 구매 가능 여부 확인
   491→			const FCosmeticItemDefinition* ItemDef = nullptr;
   492→			if (CosmeticSub->GetCatalog())
   493→			{
   494→				ItemDef = CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId);
   495→			}
   496→
   497→			bool bCanBuyWithCoin = ItemDef && ItemDef->CoinPrice > 0;
   498→			bool bCanBuyWithGem = ItemDef && ItemDef->GemPrice > 0;
   499→
   500→			ActionButton->SetIsEnabled(!bPending);
   501→
   502→			if (bPending)
   503→			{
   504→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchasing", "구매 중..."));
   505→			}
   506→			else if (bCanBuyWithCoin)
   507→			{
   508→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "PurchaseCoin", "Coin 구매"));
   509→			}
   510→			else if (bCanBuyWithGem)
   511→			{
   512→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "PurchaseGem", "Gem 구매"));
   513→			}
   514→			else
   515→			{
   516→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchase", "구매"));
   517→			}
   518→		}
   519→	}
   520→	else
   521→	{
   522→		// 인벤토리 모드
   523→		ActionButton->SetIsEnabled(true);
   524→
   525→		if (bIsEquipped)
   526→		{
   527→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   528→		}
   529→		else
   530→		{
   531→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   532→		}
   533→	}
