   609→void UCosmeticMainWindow::PopulateShopItems()
   610→{
   611→	UGameInstance* GI = GetGameInstance();
   612→	if (!GI)
   613→	{
   614→		return;
   615→	}
   616→
   617→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   618→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   619→	{
   620→		return;
   621→	}
   622→
   623→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   624→	TArray<const FCosmeticItemDefinition*> Items = Catalog->GetItemsBySlot(CurrentSlot);
   625→
   626→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   627→
   628→	int32 Index = 0;
   629→	for (const FCosmeticItemDefinition* ItemDef : Items)
   630→	{
   631→		if (!ItemDef || !ItemDef->IsValid())
   632→		{
   633→			continue;
   634→		}
   635→
   636→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   637→		if (!EntryWidget)
   638→		{
   639→			continue;
   640→		}
   641→
   642→		// 보유/장착 상태 설정
   643→		bool bOwned = CosmeticSub->HasItem(ItemDef->ItemId);
   644→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   645→
   646→		EntryWidget->SetOwned(bOwned);
   647→		EntryWidget->SetEquipped(bEquipped);
   648→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   649→
   650→		// 그리드에 추가
   651→		if (ItemGridPanel)
   652→		{
   653→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   654→		}
   655→
   656→		ItemEntryWidgets.Add(EntryWidget);
   657→		Index++;
   658→	}
   659→
   660→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d shop items"), Index);
   661→}
