	Inventory	UMETA(DisplayName = "Inventory"),
};

/**
 * 코스메틱 메인 윈도우
 *
 * 상점/인벤토리 통합 윈도우
 * - 탭으로 상점/인벤토리 전환
 * - 슬롯별 아이템 필터링
 * - 4열 그리드 레이아웃
 * - 3D 캐릭터 프리뷰
 * - 구매/장착/해제 기능
