   228→void UCosmeticMainWindow::OnActionButtonClicked()
   229→{
   230→	if (SelectedItemId.IsNone())
   231→	{
   232→		return;
   233→	}
   234→
   235→	UGameInstance* GI = GetGameInstance();
   236→	if (!GI)
   237→	{
   238→		return;
   239→	}
   240→
   241→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   242→	if (!CosmeticSub)
   243→	{
   244→		return;
   245→	}
   246→
   247→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   248→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   249→
   250→	if (CurrentMode == ECosmeticWindowMode::Shop)
   251→	{
   252→		// 상점 모드
   253→		if (CosmeticSub->HasItem(SelectedItemId))
   254→		{
   255→			// 보유 중인 아이템 → 장착 또는 해제
   256→			if (EquippedItem == SelectedItemId)
   257→			{
   258→				CosmeticSub->UnequipSlot(CurrentSlot);
   259→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d (from Shop)"), static_cast<int32>(CurrentSlot));
   260→			}
   261→			else
   262→			{
   263→				CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   264→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d (from Shop)"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   265→			}
   266→			CosmeticSub->SaveLoadoutToLocal();
   267→		}
   268→		else
   269→		{
   270→			// 미보유 아이템 → 재화 구매 우선, 불가 시 Steam 실결제
   271→			const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog() ? CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId) : nullptr;
   272→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   273→
   274→			bool bCurrencyPurchased = false;
   275→			if (ItemDef && CurrencySub)
   276→			{
   277→				if (ItemDef->CoinPrice > 0)
   278→				{
   279→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Coin);
   280→					if (bCurrencyPurchased)
   281→					{
   282→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Coin purchase requested for %s"), *SelectedItemId.ToString());
   283→					}
   284→				}
   285→
   286→				if (!bCurrencyPurchased && ItemDef->GemPrice > 0)
   287→				{
   288→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Gem);
   289→					if (bCurrencyPurchased)
   290→					{
   291→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Gem purchase requested for %s"), *SelectedItemId.ToString());
   292→					}
   293→				}
   294→			}
   295→
   296→			if (!bCurrencyPurchased)
   297→			{
   298→				UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   299→				if (PurchaseSub && !PurchaseSub->IsPurchasePending())
   300→				{
   301→					PurchaseSub->RequestPurchase(SelectedItemId);
   302→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Steam purchase requested for %s"), *SelectedItemId.ToString());
   303→				}
   304→			}
   305→		}
   306→	}
   307→	else
   308→	{
   309→		// 인벤토리 모드: 장착 또는 해제
   310→		if (EquippedItem == SelectedItemId)
   311→		{
   312→			CosmeticSub->UnequipSlot(CurrentSlot);
   313→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d"), static_cast<int32>(CurrentSlot));
   314→		}
   315→		else
   316→		{
   317→			CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   318→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   319→		}
   320→		CosmeticSub->SaveLoadoutToLocal();
   321→	}
   322→}
