   493→void UCosmeticMainWindow::RefreshActionButton()
   494→{
   495→	if (!ActionButton || !ActionButtonText)
   496→	{
   497→		return;
   498→	}
   499→
   500→	if (SelectedItemId.IsNone())
   501→	{
   502→		ActionButton->SetIsEnabled(false);
   503→		ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "SelectItem", "아이템 선택"));
   504→		return;
   505→	}
   506→
   507→	UGameInstance* GI = GetGameInstance();
   508→	if (!GI)
   509→	{
   510→		return;
   511→	}
   512→
   513→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   514→	if (!CosmeticSub)
   515→	{
   516→		return;
   517→	}
   518→
   519→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   520→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   521→	bool bIsEquipped = (EquippedItem == SelectedItemId);
   522→
   523→	if (CurrentMode == ECosmeticWindowMode::Shop)
   524→	{
   525→		// 상점 모드
   526→		if (CosmeticSub->HasItem(SelectedItemId))
   527→		{
   528→			// 보유 중인 아이템 → 장착/해제 가능
   529→			ActionButton->SetIsEnabled(true);
   530→
   531→			if (bIsEquipped)
   532→			{
   533→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   534→			}
   535→			else
   536→			{
   537→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   538→			}
   539→		}
   540→		else
   541→		{
   542→			// 미보유 아이템 → 구매
   543→			UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   544→			bool bPending = PurchaseSub && PurchaseSub->IsPurchasePending();
   545→
   546→			// 재화 구매 가능 여부 확인
   547→			const FCosmeticItemDefinition* ItemDef = nullptr;
   548→			if (CosmeticSub->GetCatalog())
   549→			{
   550→				ItemDef = CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId);
   551→			}
   552→
   553→			bool bCanBuyWithCoin = ItemDef && ItemDef->CoinPrice > 0;
   554→			bool bCanBuyWithGem = ItemDef && ItemDef->GemPrice > 0;
   555→
   556→			ActionButton->SetIsEnabled(!bPending);
   557→
   558→			if (bPending)
   559→			{
   560→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchasing", "구매 중..."));
   561→			}
   562→			else if (bCanBuyWithCoin)
   563→			{
   564→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "PurchaseCoin", "Coin 구매"));
   565→			}
   566→			else if (bCanBuyWithGem)
   567→			{
   568→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "PurchaseGem", "Gem 구매"));
   569→			}
   570→			else
   571→			{
   572→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchase", "구매"));
   573→			}
   574→		}
   575→	}
   576→	else
   577→	{
   578→		// 인벤토리 모드
   579→		ActionButton->SetIsEnabled(true);
   580→
   581→		if (bIsEquipped)
   582→		{
   583→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   584→		}
   585→		else
   586→		{
   587→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   588→		}
   589→	}
