   665→void UCosmeticMainWindow::PopulateShopItems()
   666→{
   667→	UGameInstance* GI = GetGameInstance();
   668→	if (!GI)
   669→	{
   670→		return;
   671→	}
   672→
   673→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   674→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   675→	{
   676→		return;
   677→	}
   678→
   679→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   680→	TArray<const FCosmeticItemDefinition*> Items = Catalog->GetItemsBySlot(CurrentSlot);
   681→
   682→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   683→
   684→	int32 Index = 0;
   685→	for (const FCosmeticItemDefinition* ItemDef : Items)
   686→	{
   687→		if (!ItemDef || !ItemDef->IsValid())
   688→		{
   689→			continue;
   690→		}
   691→
   692→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   693→		if (!EntryWidget)
   694→		{
   695→			continue;
   696→		}
   697→
   698→		// 보유/장착 상태 설정
   699→		bool bOwned = CosmeticSub->HasItem(ItemDef->ItemId);
   700→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   701→
   702→		EntryWidget->SetOwned(bOwned);
   703→		EntryWidget->SetEquipped(bEquipped);
   704→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   705→
   706→		// 그리드에 추가
   707→		if (ItemGridPanel)
   708→		{
   709→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   710→		}
   711→
   712→		ItemEntryWidgets.Add(EntryWidget);
   713→		Index++;
   714→	}
   715→
   716→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d shop items"), Index);
   717→}
   718→
   719→void UCosmeticMainWindow::PopulateInventoryItems()
   720→{
   721→	UGameInstance* GI = GetGameInstance();
   722→	if (!GI)
   723→	{
   724→		return;
   725→	}
   726→
   727→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   728→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   729→	{
   730→		return;
   731→	}
   732→
   733→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   734→	const TArray<FCosmeticItemInstance>& Inventory = CosmeticSub->GetInventory();
   735→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   736→
   737→	int32 Index = 0;
   738→	for (const FCosmeticItemInstance& ItemInstance : Inventory)
   739→	{
   740→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(ItemInstance.ItemId);
   741→		if (!ItemDef || !ItemDef->IsValid())
   742→		{
   743→			continue;
   744→		}
   745→
   746→		// 현재 슬롯에 해당하는 아이템만 표시
   747→		if (ItemDef->Slot != CurrentSlot)
   748→		{
   749→			continue;
   750→		}
   751→
   752→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   753→		if (!EntryWidget)
   754→		{
   755→			continue;
   756→		}
   757→
   758→		// 인벤토리 모드에서는 항상 보유 중
   759→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   760→
   761→		EntryWidget->SetOwned(true);
   762→		EntryWidget->SetEquipped(bEquipped);
   763→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   764→
   765→		// 그리드에 추가
   766→		if (ItemGridPanel)
   767→		{
   768→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   769→		}
   770→
   771→		ItemEntryWidgets.Add(EntryWidget);
   772→		Index++;
   773→	}
   774→
   775→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d inventory items"), Index);
   776→}
   777→
   778→UCosmeticItemEntryWidget* UCosmeticMainWindow::CreateItemEntry(const FCosmeticItemDefinition& Def)
   779→{
   780→	if (!ItemEntryWidgetClass)
   781→	{
   782→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CosmeticMainWindow: ItemEntryWidgetClass is not set"));
   783→		return nullptr;
   784→	}
   785→
   786→	UCosmeticItemEntryWidget* EntryWidget = CreateWidget<UCosmeticItemEntryWidget>(GetOwningPlayer(), ItemEntryWidgetClass);
   787→	if (!EntryWidget)
   788→	{
   789→		return nullptr;
   790→	}
   791→
   792→	EntryWidget->SetItemDefinition(Def);
   793→	EntryWidget->OnItemClicked.AddDynamic(this, &UCosmeticMainWindow::OnItemClicked);
   794→
   795→	return EntryWidget;
   796→}
   797→
   798→void UCosmeticMainWindow::ClearItemGrid()
   799→{
   800→	// 델리게이트 바인딩 해제 및 위젯 제거
   801→	for (UCosmeticItemEntryWidget* Entry : ItemEntryWidgets)
   802→	{
   803→		if (Entry)
   804→		{
   805→			Entry->OnItemClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnItemClicked);
   806→			Entry->RemoveFromParent();
   807→		}
   808→	}
   809→	ItemEntryWidgets.Empty();
   810→
   811→	// 그리드 클리어
   812→	if (ItemGridPanel)
   813→	{
   814→		ItemGridPanel->ClearChildren();
   815→	}
   816→}
