   292→void UWjWorldCosmeticSubsystem::ParseInventoryResult()
   293→{
   294→#if WITH_STEAM
   295→	ISteamInventory* SteamInv = SteamInventory();
   296→	if (!SteamInv || !Catalog)
   297→	{
   298→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: SteamInventory 또는 Catalog 없음"));
   299→		return;
   300→	}
   301→
   302→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   303→	{
   304→		return;
   305→	}
   306→
   307→	// 아이템 개수 확인
   308→	uint32 ItemCount = 0;
   309→	if (!SteamInv->GetResultItems(PendingResultHandle, nullptr, &ItemCount) || ItemCount == 0)
   310→	{
   311→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리: 아이템 0개"));
   312→		CachedInventory.Empty();
   313→		return;
   314→	}
   315→
   316→	// 아이템 상세 정보 가져오기
   317→	TArray<SteamItemDetails_t> ItemDetails;
   318→	ItemDetails.SetNum(ItemCount);
   319→
   320→	if (!SteamInv->GetResultItems(PendingResultHandle, ItemDetails.GetData(), &ItemCount))
   321→	{
   322→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 아이템 상세 정보 가져오기 실패"));
   323→		return;
   324→	}
   325→
   326→	// 캐시된 인벤토리 갱신
   327→	CachedInventory.Empty(ItemCount);
   328→
   329→	for (uint32 i = 0; i < ItemCount; ++i)
   330→	{
   331→		const SteamItemDetails_t& Details = ItemDetails[i];
   332→
   333→		// SteamItemDefId → ItemId 변환
   334→		FName ItemId = Catalog->SteamItemDefIdToItemId(Details.m_iDefinition);
   335→		if (ItemId.IsNone())
   336→		{
   337→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("알 수 없는 SteamItemDefId: %d"), Details.m_iDefinition);
   338→			continue;
   339→		}
   340→
   341→		// 수량 체크 (0이면 소비됨/만료됨)
   342→		if (Details.m_unQuantity == 0)
   343→		{
   344→			continue;
   345→		}
   346→
   347→		// 기존 아이템 수량 증가 또는 새로 추가
   348→		FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   349→		{
   350→			return Inst.ItemId == ItemId;
   351→		});
   352→
   353→		if (Existing)
   354→		{
   355→			Existing->Quantity += Details.m_unQuantity;
   356→		}
   357→		else
   358→		{
   359→			FCosmeticItemInstance NewItem(ItemId);
   360→			NewItem.Quantity = Details.m_unQuantity;
   361→			CachedInventory.Add(NewItem);
   362→		}
   363→
   364→		UE_LOG(LogWjWorldCosmetic, Verbose, TEXT("인벤토리 아이템: %s (DefId: %d, Qty: %d)"),
   365→			*ItemId.ToString(), Details.m_iDefinition, Details.m_unQuantity);
   366→	}
   367→
   368→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 파싱 완료: %d개 아이템"), CachedInventory.Num());
   369→#endif
   370→}
