   372→bool UWjWorldCosmeticSubsystem::AddPromoItem(int32 SteamItemDefId)
   373→{
   374→#if WITH_STEAM
   375→	ISteamInventory* SteamInv = SteamInventory();
   376→	if (!SteamInv)
   377→	{
   378→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddPromoItem: Steam Inventory API 사용 불가"));
   379→		return false;
   380→	}
   381→
   382→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamItemDefId);
   383→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
