   446→
   447→	ISteamInventory* SteamInv = SteamInventory();
   448→	if (!SteamInv)
   449→	{
   450→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam Inventory API 사용 불가"));
   451→		return false;
   452→	}
   453→
   454→	if (!Catalog)
   455→	{
   456→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 카탈로그 없음"));
   457→		return false;
   458→	}
   459→
   460→	int32 SteamDefId = Catalog->ItemIdToSteamItemDefId(ItemId);
