   464→		return false;
   465→	}
   466→
   467→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamDefId);
   468→	uint32 Quantity = 1;
   469→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
