    40→bool UWjWorldPurchaseSubsystem::RequestPurchase(FName ItemId)
    41→{
    42→	if (CurrentState == EPurchaseState::Pending)
    43→	{
    44→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("이미 구매가 진행 중입니다 (PendingItem: %s)."), *PendingItemId.ToString());
    45→		return false;
    46→	}
    47→
    48→	if (ItemId.IsNone())
    49→	{
    50→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("유효하지 않은 ItemId입니다."));
    51→		return false;
    52→	}
    53→
    54→#if WITH_STEAM
    55→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
    56→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
    57→	{
    58→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CosmeticSubsystem 또는 카탈로그가 없습니다."));
    59→		return false;
    60→	}
    61→
    62→	int32 SteamDefId = CosmeticSub->GetCatalog()->ItemIdToSteamItemDefId(ItemId);
    63→	if (SteamDefId == 0)
    64→	{
    65→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'에 대한 SteamItemDefId를 찾을 수 없습니다."), *ItemId.ToString());
    66→		return false;
    67→	}
    68→
    69→	ISteamInventory* SteamInv = SteamInventory();
    70→	if (!SteamInv)
    71→	{
    72→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam Inventory API를 사용할 수 없습니다."));
    73→		return false;
    74→	}
    75→
    76→	// 기존 핸들 정리
    77→	if (PurchaseResultHandle != k_SteamInventoryResultInvalid)
    78→	{
    79→		SteamInv->DestroyResult(PurchaseResultHandle);
    80→		PurchaseResultHandle = k_SteamInventoryResultInvalid;
    81→	}
    82→
    83→	// Steam StartPurchase를 통해 결제 오버레이 요청
    84→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamDefId);
    85→	uint32 Quantity = 1;
    86→
    87→	if (SteamInv->StartPurchase(&ItemDef, &Quantity, 1))
    88→	{
    89→		CurrentState = EPurchaseState::Pending;
    90→		PendingItemId = ItemId;
    91→		PurchaseStartTime = GetWorld() ? GetWorld()->GetTimeSeconds() : 0.f;
    92→		StartPurchasePolling();
    93→
    94→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 구매 요청 시작: ItemDefId=%d, ItemId=%s"), SteamDefId, *ItemId.ToString());
    95→		return true;
    96→	}
    97→	else
    98→	{
    99→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam StartPurchase 실패: ItemDefId=%d"), SteamDefId);
   100→		return false;
   101→	}
   102→#else
   103→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 미지원 환경 - 구매 시뮬레이션: %s"), *ItemId.ToString());
   104→
   105→	// 비 Steam 환경에서는 즉시 성공 처리 (테스트용)
   106→	CurrentState = EPurchaseState::Pending;
   107→	PendingItemId = ItemId;
   108→	HandlePurchaseResult(true);
   109→	return true;
   110→#endif
   111→}
   112→
   113→void UWjWorldPurchaseSubsystem::HandlePurchaseResult(bool bSuccess)
   114→{
   115→	if (bSuccess)
   116→	{
   117→		CurrentState = EPurchaseState::Completed;
   118→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 완료: %s"), *PendingItemId.ToString());
   119→
   120→		RefreshInventoryAfterPurchase();
   121→	}
   122→	else
   123→	{
   124→		CurrentState = EPurchaseState::Failed;
   125→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("구매 실패: %s"), *PendingItemId.ToString());
   126→	}
   127→
   128→	OnPurchaseComplete.Broadcast(PendingItemId, bSuccess);
   129→
   130→	// 상태 리셋 (다음 구매를 위해)
   131→	FName CompletedItemId = PendingItemId;
   132→	PendingItemId = NAME_None;
   133→	CurrentState = EPurchaseState::Idle;
   134→}
