   136→void UWjWorldPurchaseSubsystem::RefreshInventoryAfterPurchase()
   137→{
   138→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   139→	if (CosmeticSub)
   140→	{
   141→#if WITH_STEAM
   142→		CosmeticSub->RequestInventoryRefresh();
   143→#else
   144→		// 비 Steam 환경: 로컬로 아이템 부여
   145→		CosmeticSub->GrantItemLocally(PendingItemId, 1);
   146→#endif
   147→	}
   148→}
