    86→void UWjWorldCurrencySubsystem::TriggerMatchReward(bool bIsWinner)
    87→{
    88→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    89→	if (!Settings)
    90→	{
    91→		return;
    92→	}
    93→
    94→	int32 GeneratorDefId = bIsWinner ? Settings->MatchWinRewardDefId : Settings->MatchLossRewardDefId;
    95→
    96→	UE_LOG(LogWjWorldCurrency, Log, TEXT("매치 보상 트리거: %s (GeneratorDefId: %d)"),
    97→		bIsWinner ? TEXT("승리") : TEXT("패배"), GeneratorDefId);
    98→
    99→#if WITH_STEAM
   100→	ISteamInventory* SteamInv = SteamInventory();
   101→	if (SteamInv)
   102→	{
   103→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   104→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   105→
   106→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   107→		{
   108→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam TriggerItemDrop 요청 성공 (DefId: %d)"), GeneratorDefId);
   109→			SteamInv->DestroyResult(ResultHandle);
   110→
   111→			// 인벤토리 갱신으로 잔액 반영
   112→			UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   113→			if (CosmeticSub)
   114→			{
   115→				CosmeticSub->RequestInventoryRefresh();
   116→			}
   117→		}
   118→		else
   119→		{
   120→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam TriggerItemDrop 실패 (DefId: %d)"), GeneratorDefId);
   121→		}
   122→
   123→		return;
   124→	}
   125→#endif
   126→
   127→	// 비Steam 폴백: 로컬 잔액 직접 증가
   128→	int32 RewardAmount = bIsWinner ? 50 : 10;
   129→	GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   130→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 매치 보상 지급: %d Coin"), RewardAmount);
   131→}
