   496→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   497→{
   498→#if WITH_STEAM
   499→	if (!bGemPurchasePending)
   500→	{
   501→		StopGemPurchasePolling();
   502→		return;
   503→	}
   504→
   505→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   506→	// 인벤토리 변경을 감지하여 완료 판단
   507→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   508→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   509→
   510→	// 간단한 타임아웃 처리 (300초)
   511→	static float GemPurchaseStartTime = 0.0f;
   512→	UWorld* World = GetWorld();
   513→	if (World)
   514→	{
   515→		if (GemPurchaseStartTime == 0.0f)
   516→		{
   517→			GemPurchaseStartTime = World->GetTimeSeconds();
   518→		}
   519→
   520→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   521→		if (ElapsedTime > 300.0f)
   522→		{
   523→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   524→			bGemPurchasePending = false;
   525→			GemPurchaseStartTime = 0.0f;
   526→			StopGemPurchasePolling();
   527→		}
   528→	}
   529→#else
   530→	StopGemPurchasePolling();
   531→#endif
   532→}
